mapper.select:
select

from safety_goods_out_detail_goods
where 1 = 1


  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

select
,is_history_exce FROM ( SELECT p.flow_id,p.flow_no,p.`subject`,DATE_FORMAT(p.create_time,'%Y-%m-%d %H:%i:%s') create_time_str, case when (p.outside_name is null or p.outside_name='') then p.goout_emp_name else outside_name end goout_emp_name,p.out_factory_name,p.examine_emp_name,p.`status`, p.out_type_name,g.process_id,g.id,g.goods_code,g.goods_name,g.goods_unit,g.goods_num, '' vehicle_no,'' vin_no,g.remark,p.vehicle_no process_vehicle_no, e.is_exception is_history_exce from safety.safety_goods_out_detail_goods g INNER JOIN safety.safety_goods_out_process p on g.process_id = p.id LEFT JOIN safety.safety_goods_out_exception e on p.id = e.process_id where 1 = 1
UNION all SELECT p.flow_id,p.flow_no,p.`subject`,DATE_FORMAT(p.create_time,'%Y-%m-%d %H:%i:%s') create_time_str, case when (p.outside_name is null or p.outside_name='') then p.goout_emp_name else outside_name end goout_emp_name,p.out_factory_name,p.examine_emp_name,p.`status`, p.out_type_name,v.process_id,v.id,'' goods_code,'' goods_name,'' goods_unit, '' goods_num,v.vehicle_no,v.vin_no,'' remark,p.vehicle_no process_vehicle_no, e.is_exception is_history_exce from safety.safety_goods_out_detail_vehicle v INNER JOIN safety.safety_goods_out_process p on v.process_id = p.id LEFT JOIN safety.safety_goods_out_exception e on p.id = e.process_id where 1 = 1
) as cur_tmp where 1 = 1
and is_history_exce = #{isHistoryExce}
order by create_time_str desc
limit ${offset}, ${limit}
limit ${limit}

select count(1) FROM ( SELECT p.flow_id,p.flow_no,p.`subject`,DATE_FORMAT(p.create_time,'%Y-%m-%d %H:%i:%s') create_time,p.goout_emp_name,p.out_factory_name,p.examine_emp_name,p.`status`, p.out_type_name,g.process_id,g.id,g.goods_code,g.goods_name,g.goods_unit,g.goods_num,'' vehicle_no,'' vin_no,g.remark, p.vehicle_no process_vehicle_no, e.is_exception is_history_exce from safety.safety_goods_out_detail_goods g INNER JOIN safety.safety_goods_out_process p on g.process_id = p.id LEFT JOIN safety.safety_goods_out_exception e on p.id = e.process_id where 1 = 1
UNION all SELECT p.flow_id,p.flow_no,p.`subject`,DATE_FORMAT(p.create_time,'%Y-%m-%d %H:%i:%s') create_time,p.goout_emp_name,p.out_factory_name,p.examine_emp_name,p.`status`, p.out_type_name,v.process_id,v.id,'' goods_code,'' goods_name,'' goods_unit,'' goods_num,v.vehicle_no,v.vin_no,'' remark, p.vehicle_no process_vehicle_no, e.is_exception is_history_exce from safety.safety_goods_out_detail_vehicle v INNER JOIN safety.safety_goods_out_process p on v.process_id = p.id LEFT JOIN safety.safety_goods_out_exception e on p.id = e.process_id where 1 = 1
) as cur_tmp where 1 = 1
and is_history_exce = #{isHistoryExce}

select
,is_history_exce FROM ( SELECT p.flow_id,p.flow_no,p.`subject`,DATE_FORMAT(p.create_time,'%Y-%m-%d %H:%i:%s') create_time_str, case when (p.outside_name is null or p.outside_name='') then p.goout_emp_name else outside_name end goout_emp_name,p.out_factory_name,p.examine_emp_name,p.`status`, p.out_type_name,g.process_id,g.id,g.goods_code,g.goods_name,g.goods_unit,g.goods_num, '' vehicle_no,'' vin_no,g.remark,p.vehicle_no process_vehicle_no, e.is_exception is_history_exce from safety.safety_goods_out_detail_goods g INNER JOIN safety.safety_goods_out_process p on g.process_id = p.id LEFT JOIN safety.safety_goods_out_exception e on p.id = e.process_id where 1 = 1
) as cur_tmp order by create_time_str desc
